import * as THREE from '../three.module.js';
import {batWorldPoint,v} from '../physics.js';
// World-space diagnostics only; never affect controller targets or collision.
export class PhysicalDebugOverlay {
 constructor(scene){this.group=new THREE.Group();scene.add(this.group);this.lines=new THREE.LineSegments(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:0xffc974,depthTest:false}));this.points=new THREE.Points(new THREE.BufferGeometry(),new THREE.PointsMaterial({color:0xffedb7,size:.025,depthTest:false}));this.group.add(this.lines,this.points);}
 update(p,visible){this.group.visible=visible;if(!visible||!p.physicalBat)return;const lines=[],points=[],segment=(a,b)=>lines.push(a.x,a.y,a.z,b.x,b.y,b.z),point=a=>points.push(a.x,a.y,a.z);for(const [key,y] of [['top',.56],['bottom',.465]]){const actual=batWorldPoint(v(0,y,0),p),target=p.humanTarget[key];segment(actual,target);point(target);point(actual);}const c=p.physicalBat.centerOfMass,w=p.physicalBat.angularVelocity;point(c);segment(c,v(c.x+w.x*.025,c.y+w.y*.025,c.z+w.z*.025));if(p.balance){const b=p.balance,com=b.centerOfMass;point(com);segment(com,v(com.x,.015,com.z));segment(b.baseOfSupport[0],b.baseOfSupport[1]);for(const foot of b.baseOfSupport){point(foot);for(let i=0;i<24;i++){const a=i*Math.PI/12,z=(i+1)*Math.PI/12;segment(v(foot.x+Math.cos(a)*.14,.012,foot.z+Math.sin(a)*.14),v(foot.x+Math.cos(z)*.14,.012,foot.z+Math.sin(z)*.14));}}}this.lines.geometry.setAttribute('position',new THREE.Float32BufferAttribute(lines,3));this.points.geometry.setAttribute('position',new THREE.Float32BufferAttribute(points,3));this.lines.geometry.computeBoundingSphere();this.points.geometry.computeBoundingSphere();}
}
